#!/bin/sh
# Prints the three IP addresses that appear most often in access.log,
# most frequent first; ties broken by first appearance in the log.
set -eu
cd "$(dirname "$0")"

awk '{
    ip = $1
    if (!(ip in count)) {
        order[ip] = ++n
    }
    count[ip]++
}
END {
    for (ip in count) {
        print count[ip], order[ip], ip
    }
}' access.log | sort -k1,1nr -k2,2n | head -n 3 | awk '{print $3}'
